using System.Diagnostics.CodeAnalysis;

namespace ChogGames.Core.Rooms;

/// <summary>
/// Private room invite code (ENG-001): six characters without look-alikes (no 0, O, 1, I or L), so it is easy to
/// read aloud and type on a phone. Codes are generated by the server; input is accepted in any letter case.
/// </summary>
public readonly record struct RoomCode
{
    public const int Length = 6;

    public const string Alphabet = "23456789ABCDEFGHJKMNPQRSTUVWXYZ";

    public string Value { get; }

    private RoomCode(string value) => Value = value;

    public static bool TryParse([NotNullWhen(true)] string? input, out RoomCode code)
    {
        code = default;
        var value = input?.Trim().ToUpperInvariant();
        if (value is null || value.Length != Length || value.Any(c => !Alphabet.Contains(c)))
        {
            return false;
        }

        code = new RoomCode(value);
        return true;
    }

    public override string ToString() => Value;
}

/// <summary>Draws new room codes; production uses a cryptographically secure source (ENG-008).</summary>
public interface IRoomCodeGenerator
{
    RoomCode Next();
}
